'use strict';
const {chart,BEAT,Run,melody,duration}=Kifu;
const $=id=>document.getElementById(id), canvas=$('board'),ctx=canvas.getContext('2d');
let audio,master,nodes=[],run=new Run(),active=false,startAt=0,mode='direct',offset=0,feedback=[],frame=0,lastTime=0;
function tone(midi,time,length,gain=.1,type='triangle'){const osc=audio.createOscillator(),env=audio.createGain();osc.type=type;osc.frequency.value=440*2**((midi-69)/12);env.gain.setValueAtTime(0,time);env.gain.linearRampToValueAtTime(gain,time+.008);env.gain.exponentialRampToValueAtTime(.0001,time+length);osc.connect(env).connect(master);osc.start(time);osc.stop(time+length+.02);nodes.push(osc);}
function tick(time,accent=false){const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(accent?1800:1100,time);o.frequency.exponentialRampToValueAtTime(350,time+.035);g.gain.setValueAtTime(.16,time);g.gain.exponentialRampToValueAtTime(.0001,time+.055);o.connect(g).connect(master);o.start(time);o.stop(time+.06);nodes.push(o);}
function music(){for(let k=-4;k<0;k++)tick(startAt+k*BEAT,k===-4);let beat=0;for(let repeat=0;repeat<2;repeat++)for(const [note,len] of melody){tone(note+(repeat?12:0),startAt+beat*BEAT,len*BEAT*.85,.13,'triangle');if(repeat)tone(note,startAt+beat*BEAT,len*BEAT*.7,.035,'sine');beat+=len;}
 for(let b=0;b<128;b++){const base=[48,48,43,48][Math.floor(b/4)%4];tone(b%2?base+7:base,startAt+b*BEAT,BEAT*.6,.075,'sine');if(b%2===0)tone(35,startAt+b*BEAT,.085,.14,'sine');else tone(86,startAt+b*BEAT,.025,.018,'triangle');} }
function soundStop(){for(const n of nodes){try{n.stop();n.disconnect();}catch{}}nodes=[];}
function setControls(playing){$('start').disabled=playing;$('stop').hidden=!playing;$('modes').disabled=playing;$('offset').disabled=playing;document.body.classList.toggle('playing',playing);}
async function start(){if(active)return;$('start').disabled=true;try{if(!audio){audio=new (window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.connect(audio.destination);}await audio.resume();soundStop();master.gain.value=Number($('volume').value)/100*.65;mode=document.querySelector('input[name=mode]:checked').value;offset=Number($('offset').value)/1000;run=new Run();feedback=[];lastTime=-4*BEAT;startAt=audio.currentTime+4*BEAT+.12;active=true;$('result').hidden=true;setControls(true);$('hint').textContent=mode==='direct'?'赤い輪が重なる交点をタップ。':'盤のどこでもタップ、または Space。';$('score').textContent='0000';$('combo').textContent='0';music();}catch(e){active=false;setControls(false);$('hint').textContent='音を開始できませんでした。もう一度お試しください。';console.error(e);} }
function finish(stopped=false){active=false;soundStop();setControls(false);$('start').innerHTML='もう一度、はじめる <span>↗</span>';$('phase').textContent=stopped?'STOPPED':'COMPLETE';if(stopped){$('hint').textContent='停止しました。はじめから演奏できます。';$('judge').textContent='ひと休み。';return;}const perfect=run.results.filter(r=>r?.kind==='perfect').length,good=run.results.filter(r=>r?.kind==='good').length,assist=chart.length-perfect-good;$('resultText').innerHTML=`ぴったり ${perfect} 手 · 成功 ${good} 手 · 補助 ${assist} 手<br>最高 ${run.best} コンボ / ${run.score} 点`;$('result').hidden=false;$('judge').textContent='フレーズ完走';$('hint').textContent='打ち方を変えて、同じ曲を比べてみよう。';}
function input(x,y){if(!active)return;const t=audio.currentTime-startAt-offset;const r=run.hit(t,x,y,mode);if(r){tick(audio.currentTime, r.kind==='perfect');consume();}}
function consume(){for(const event of run.events.splice(0)){const m=chart[event.i];feedback.push({x:m.x,y:m.y,at:performance.now(),kind:event.kind,captured:event.captured});$('judge').textContent=event.kind==='perfect'?'ぴったり！':event.kind==='good'?(event.error<0?'いいね · 少し早い':'いいね · 少し遅い'):'補助で、次へ';$('score').textContent=String(run.score).padStart(4,'0');$('combo').textContent=run.combo;$('moves').textContent=`${event.i+1} / ${chart.length} 手${event.captured.length?' · '+event.captured.length+'石を取った！':''}`;}}
function draw(){const s=720,p=64,d=74;ctx.setTransform(canvas.width/s,0,0,canvas.height/s,0,0);ctx.clearRect(0,0,s,s);ctx.fillStyle='#e7cd96';ctx.fillRect(0,0,s,s);for(let j=0;j<80;j++){ctx.strokeStyle=`rgba(123,90,37,${.012+(j%4)*.003})`;ctx.beginPath();ctx.moveTo(0,j*10);ctx.bezierCurveTo(230,j*10-4,450,j*10+5,720,j*10);ctx.stroke();}ctx.strokeStyle='#8f784e';ctx.lineWidth=1.2;for(let i=0;i<9;i++){ctx.beginPath();ctx.moveTo(p,p+i*d);ctx.lineTo(p+8*d,p+i*d);ctx.moveTo(p+i*d,p);ctx.lineTo(p+i*d,p+8*d);ctx.stroke();ctx.fillStyle='#998158';ctx.font='13px Arial';ctx.textAlign='center';ctx.fillText('ABCDEFGHJ'[i],p+i*d,33);ctx.fillText(String(9-i),30,p+i*d+4);}for(const [x,y] of [[2,2],[6,2],[4,4],[2,6],[6,6]]){ctx.fillStyle='#77613d';ctx.beginPath();ctx.arc(p+x*d,p+y*d,4,0,7);ctx.fill();}
 run.board.forEach((color,i)=>{if(!color)return;const x=p+i%9*d,y=p+Math.floor(i/9)*d;ctx.shadowColor='#493b3440';ctx.shadowBlur=8;ctx.shadowOffsetY=4;const g=ctx.createRadialGradient(x-10,y-12,2,x,y,29);g.addColorStop(0,color===1?'#555a53':'#fffdf5');g.addColorStop(1,color===1?'#1b211d':'#d4d5c8');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,29,0,7);ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;});
 const time=active?audio.currentTime-startAt-offset:lastTime;let i=active?run.cursor:0;if(!active&&run.cursor)i=chart.length;
 for(let k=1;k>=0;k--){let m=chart[i+k];if(!m)continue;let dt=m.time-time;if(active&&dt>BEAT*4)continue;const x=p+m.x*d,y=p+m.y*d;ctx.globalAlpha=k?.35:1;ctx.strokeStyle='#c44e36';ctx.lineWidth=k?2:3;ctx.beginPath();ctx.arc(x,y,k?13:26,0,7);ctx.stroke();if(!k){const r=26+Math.max(0,Math.min(dt/(BEAT*2),1))*32;ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.stroke();ctx.fillStyle='#c44e36';ctx.font='bold 18px Arial';ctx.textAlign='center';ctx.fillText(i+1,x,y+6);}ctx.globalAlpha=1;}
 feedback=feedback.filter(f=>performance.now()-f.at<550);for(const f of feedback){const age=(performance.now()-f.at)/550;ctx.globalAlpha=1-age;ctx.lineWidth=3;ctx.strokeStyle=f.kind==='assist'?'#777f69':'#c44e36';ctx.beginPath();ctx.arc(p+f.x*d,p+f.y*d,30+age*26,0,7);ctx.stroke();for(const index of f.captured){ctx.beginPath();ctx.arc(p+index%9*d,p+Math.floor(index/9)*d,29*(1-age),0,7);ctx.stroke();}ctx.globalAlpha=1;}
}
function loop(){if(active){const musicalTime=audio.currentTime-startAt;lastTime=musicalTime-offset;run.update(lastTime);consume();$('phase').textContent=musicalTime<0?'COUNT IN · '+Math.min(4,Math.ceil(-musicalTime/BEAT)):'PLAYING · '+(mode==='direct'?'TAP':'SPACE');if(musicalTime<0)$('judge').textContent=String(Math.min(4,Math.ceil(-musicalTime/BEAT)));$('progress').style.width=Math.min(100,Math.max(0,musicalTime/duration*100))+'%';const remain=Math.ceil(Math.max(0,duration-musicalTime));$('time').textContent=String(Math.floor(remain/60)).padStart(2,'0')+':'+String(remain%60).padStart(2,'0');if(musicalTime>duration+.5)finish();}draw();frame=requestAnimationFrame(loop);}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();input(((e.clientX-r.left)/r.width*720-64)/74,((e.clientY-r.top)/r.height*720-64)/74);});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&active&&mode==='key'&&!['INPUT','BUTTON','SUMMARY'].includes(document.activeElement.tagName)){e.preventDefault();if(!e.repeat)input(0,0);}});
$('start').onclick=()=>{start();$('start').blur();};$('again').onclick=()=>{start();$('again').blur();};$('stop').onclick=()=>finish(true);$('volume').oninput=()=>{if(master)master.gain.value=Number($('volume').value)/100*.65;};$('offset').oninput=()=>$('offsetValue').textContent=$('offset').value+' ms';
document.addEventListener('visibilitychange',()=>{if(document.hidden&&active)finish(true);});
function resize(){const rect=canvas.getBoundingClientRect();canvas.width=canvas.height=Math.round(rect.width*Math.min(devicePixelRatio||1,2));}window.addEventListener('resize',resize);resize();loop();
